on conflict (id) do update set
  nombre = excluded.nombre,
  dni = coalesce(excluded.dni, socios.dni),
  celular = coalesce(excluded.celular, socios.celular),
  saldo_pendiente = excluded.saldo_pendiente,
  adelanto_pagado = excluded.adelanto_pagado,
  turno = excluded.turno,
  coach_asignado = excluded.coach_asignado,
  fecha_inicio = excluded.fecha_inicio,
  fecha_fin = excluded.fecha_fin;

-- Vincular automáticamente el usuario de Supabase Auth si ya inició sesión
update public.socios
set user_id = p.id
from public.profiles p
where (p.email = socios.email or (socios.dni is not null and p.dni = socios.dni))
  and socios.user_id is null;

